//! 🧪️ Original paid semantic metadata survives exclusive payload loans and a separate granted acknowledgement.
use super::*;
fn observe<T>(body:impl FnOnce()->T)->(T,(usize,usize)){let(value,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(body);(value,(heap.requested_bytes,heap.released_bytes))}
#[test]
fn original_outcome_descriptors_keep_same_payload_and_receipt_until_paid_ack(){
 let law:serde_json::Value=serde_json::from_str(include_str!("../🧫️fixtures/🔣️.json")).unwrap();let row=&law["grant"];let grant=RetainedCloneGrant{maximum_items:row[0].as_u64().unwrap()as usize,maximum_copy_bytes:row[1].as_u64().unwrap()as usize,maximum_capacity_bytes:row[2].as_u64().unwrap()as usize,maximum_release_bytes:row[3].as_u64().unwrap()as usize,maximum_depth:row[4].as_u64().unwrap()as usize};
 let operation=OperationId(72013);let generation=Generation(19);let cancel=root_cancel_token();
 for variant in 0..6{for pages in[0,1,32]{
  let((mut payload,mut output,mut ledger),birth)=observe(||{let ledger=Arc::new(JobPayloadOperationLedger::new(operation,generation));let mut payload=RetainedJobPayload::empty(JobPayloadStream::Preview);for index in 0..pages{let mut source=JobPayloadPageSource::new();unsafe{source.storage.as_mut_ptr().cast::<u8>().write(index as u8);}ledger.reserve(JobPayloadStream::Preview,source.allocated_capacity_bytes()).unwrap();payload.pages[index]=Some(JobPayloadPage{source,length:1});payload.page_count+=1;payload.length+=1;}if pages>0{*payload.ledger=Some(Arc::clone(&ledger));}(payload,RetainedJobPayload::empty(JobPayloadStream::CommitOutput),Some(ledger))});
  let header=std::ptr::addr_of!(payload);let page=payload.page(0).map(|value|value.as_ptr());let mut sequence=0;let mut recipient=RetainedCloneProgress::default();let mut cx=StepContext::with_payload_ledger(operation,generation,StepBudget::new(1,u64::MAX,grant),cancel.clone(),logical_now_us,ClockStride::new(),&mut sequence,Arc::clone(ledger.as_ref().unwrap()),&mut recipient);
  let(mut descriptor,heap)=observe(||match variant{0=>JobOutcomeBorrow::admit_yield(&mut cx),1=>JobOutcomeBorrow::admit_preview(&mut cx,&payload),2=>JobOutcomeBorrow::admit_checkpoint(&mut cx,&payload,17),3=>JobOutcomeBorrow::admit_complete(&mut cx,Some(&payload),Some(&output)),4=>JobOutcomeBorrow::admit_cancelled(&mut cx),5=>JobOutcomeBorrow::admit_fault(&mut cx,&payload),_=>unreachable!()}.unwrap().unwrap().into_descriptor());assert_eq!(heap,(0,0));assert_eq!(cx.retained_progress(),RetainedCloneProgress{copied_items:1,..Default::default()});assert_eq!(descriptor.admission().progress(),cx.retained_progress());drop(cx);
  let(view,heap)=observe(||match variant{0=>descriptor.yielded(),1=>descriptor.preview(&payload),2=>descriptor.checkpoint(&payload),3=>descriptor.complete(Some(&payload),Some(&output)),4=>descriptor.cancelled(),5=>descriptor.fault(&payload),_=>unreachable!()}.unwrap());assert_eq!(heap,(0,0));assert!(std::ptr::eq(view.admission(),descriptor.admission()));let original=match view{JobOutcomeView::PreviewReady{payload,..}=>Some(payload),JobOutcomeView::CheckpointReady{state,applied_progress,..}=>{assert_eq!(applied_progress,17);Some(state)},JobOutcomeView::Complete{state,output,..}=>{assert!(output.unwrap().terminal_is_empty());state},JobOutcomeView::Fault{detail,..}=>Some(detail),_=>None};if let Some(original)=original{assert!(std::ptr::eq(original,header));assert_eq!(original.page(0).map(|value|value.as_ptr()),page);}
  if variant==1{let alternate=RetainedJobPayload::empty(JobPayloadStream::Preview);let(result,heap)=observe(||descriptor.preview(&alternate));assert!(result.is_err());assert_eq!(heap,(0,0));}
  for denied in[RetainedCloneGrant{maximum_items:0,..grant},RetainedCloneGrant{maximum_depth:0,..grant}]{let(step,heap)=observe(||descriptor.acknowledge(denied));assert_eq!(step.progress(),Default::default());assert_eq!(heap,(0,0));assert!(!descriptor.is_acknowledged());assert_eq!(std::ptr::addr_of!(payload),header);}
  let(step,heap)=observe(||descriptor.acknowledge(RetainedCloneGrant{maximum_copy_bytes:0,..grant}));assert_eq!(step.progress(),RetainedCloneProgress{copied_items:1,copied_bytes:0,..Default::default()});assert_eq!(heap,(0,0));assert!(descriptor.is_acknowledged());
  let mut slot=JobOutcomeDescriptorSlot::empty();assert!(slot.retain(descriptor).is_ok());assert_eq!(slot.retirement_demands().copy_bytes,0);let original=slot.original().unwrap()as*const JobOutcomeDescriptor;let(step,heap)=observe(||slot.close_step(RetainedCloneGrant{maximum_items:0,..grant}));assert_eq!(step.progress(),Default::default());assert_eq!(heap,(0,0));assert_eq!(slot.original().unwrap()as*const JobOutcomeDescriptor,original);let(step,heap)=observe(||slot.close_step(RetainedCloneGrant{maximum_copy_bytes:0,..grant}));assert_eq!(step.progress(),RetainedCloneProgress{copied_items:1,copied_bytes:0,..Default::default()});assert!(slot.is_empty());assert_eq!(heap,(0,0));let(_,heap)=observe(||drop(slot));assert_eq!(heap,(0,0));let mut released=birth.1;for original in[&mut payload,&mut output]{while !original.terminal_is_empty(){let(step,heap)=observe(||original.close_step(grant).unwrap());assert!(step.progress().fits(grant));assert_eq!(heap,(step.progress().retained_capacity_bytes,step.progress().released_bytes));released+=heap.1;}}let(step,heap)=observe(||crate::component::payload_retirement::close_ledger(&mut ledger,grant).unwrap());assert!(step.progress().fits(grant));assert_eq!(heap,(step.progress().retained_capacity_bytes,step.progress().released_bytes));released+=heap.1;assert_eq!(birth.0,released);let((),heap)=observe(||{drop(payload);drop(output);});assert_eq!(heap,(0,0));println!("[DEBUG] original descriptor variant={variant} pages={pages} samePayload sameAdmission metadataCopy0 independentACK deniedHeap0 physical={released} terminalDrop0");
 }}
}
